      responsive &&
      breakpoint &&
      (breakpoint.borderSize[borderSize] || borderSize);
    // only compute an offset if we actually have a responsiveMetric
    const responsiveBorderOffset =
      responsiveMetric &&
      responsiveBorderMetric &&
      `${
        parseMetricToNum(responsiveMetric) / 2 - parseMetricToNum(responsiveBorderMetric) / 2
      }px`;
>>>>>>> REPLACE
```

With that change, when you pass `gap="10px"` and `border="between"`, the code will skip the responsive‐offset branch (because `responsiveMetric` is undefined) and you will no longer get a `.match`‐on‐`undefined` error.
